private function secure_remote_host($host) {
    if (!is_string($host)) return false;
    $host = rtrim(trim($host), '/');
    $parts = wp_parse_url($host);
    if (!$parts || !isset($parts['scheme'], $parts['host']) || strtolower($parts['scheme']) !== 'https' || isset($parts['user']) || isset($parts['pass']) || isset($parts['query']) || isset($parts['fragment'])) return false;
    return wp_http_validate_url($host) ? $host : false;
}
private function secure_xmlrpc_query($client, $host, $method, $arguments) {
